/**
 * Экран броска S10: игрок тапом «бросает» кубики, они падают сверху на текст и отскакивают.
 *
 * Порядок такой:
 *   1. на экране подсказка «Коснись экрана, чтобы бросить»;
 *   2. тап — кубики влетают сверху в точке касания и падают вниз, отскакивая от «текста»;
 *   3. когда они остановились, крупно появляется «Успех» / «Неудача» (у трёхветвевых проверок
 *      ещё «Почти получилось»);
 *   4. экран сам закрывается, и игра читает следующий отрывок.
 *
 * Ни вычислений, ни кнопок: единственное действие игрока — бросок.
 * Кубики — three.js на прозрачном canvas поверх текста (`src/three/diceScene.ts`).
 * Без WebGL работает плоский вариант: те же кубики падают по CSS-анимации.
 */

import { useEffect, useRef, useState } from 'preact/hooks';
import type { JSX } from 'preact';

import type { CheckVerdict, GameState } from '../../engine/engine.ts';

type Roll = NonNullable<GameState['lastRoll']>;

declare global {
  interface Window {
    /** Состояние броска: значения кубиков, фаза, вердикт и режим (для тестов и отладки). */
    __NARNIA_DICE__?: {
      values: number[];
      phase: 'ready' | 'fall' | 'verdict';
      verdict: CheckVerdict;
      /** '3d' — настоящие кубики three.js, 'dom' — запасной плоский вариант. */
      mode: '3d' | 'dom';
    };
  }
}

const VERDICT_TEXT: Record<CheckVerdict, string> = {
  success: 'Успех',
  failure: 'Неудача',
  mixed: 'Почти получилось',
};

const VERDICT_NOTE: Record<CheckVerdict, string> = {
  success: 'Кубики на твоей стороне',
  failure: 'В этот раз не вышло',
  mixed: 'Наполовину получилось',
};

/** Падение и отскоки: 1.6 с — кубики успевают отскочить два-три раза. */
const FALL_SECONDS = 1.6;

function hasWebGL(): boolean {
  try {
    const canvas = document.createElement('canvas');
    return Boolean(canvas.getContext('webgl2') ?? canvas.getContext('webgl'));
  } catch {
    return false;
  }
}

export function DiceOverlay(props: {
  roll: Roll;
  onClose: () => void;
}): JSX.Element {
  const { roll } = props;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [phase, setPhase] = useState<'ready' | 'fall' | 'verdict'>('ready');
  const [mode, setMode] = useState<'3d' | 'dom'>(hasWebGL() ? '3d' : 'dom');
  const [faces, setFaces] = useState<[number, number]>(roll.dice);
  const timers = useRef<number[]>([]);
  const closed = useRef(false);
  const sceneRef = useRef<{ roll: (values: number[], seed?: number, dropX?: number) => void } | null>(null);

  const showVerdict = (): void => {
    setPhase('verdict');
    window.__NARNIA_DICE__ = { values: roll.dice, phase: 'verdict', verdict: roll.verdict, mode };
    // вердикт держим недолго: игра сама читает следующий отрывок
    timers.current.push(window.setTimeout(() => {
      if (closed.current) return;
      closed.current = true;
      props.onClose();
    }, 1250));
  };

  // --- 3D-кубики поверх текста: сцена готова и ждёт тапа ---
  useEffect(() => {
    if (mode !== '3d') return;
    let disposed = false;
    let detach = (): void => {};

    (async () => {
      try {
        const module = await import('../../three/diceScene.ts');
        if (disposed || !canvasRef.current) return;
        const scene = new module.DiceScene(canvasRef.current, {
          fall: FALL_SECONDS,
          hold: 0.2,
          onSettled: () => {
            if (!disposed) showVerdict();
          },
        });
        sceneRef.current = scene;
        const resize = (): void => {
          scene.resize(window.innerWidth, window.innerHeight, window.devicePixelRatio || 1);
        };
        resize();
        window.addEventListener('resize', resize);
        detach = () => window.removeEventListener('resize', resize);
        window.__NARNIA_DICE__ = { values: roll.dice, phase: 'ready', verdict: roll.verdict, mode };
      } catch {
        setMode('dom');
      }
    })();

    return () => {
      disposed = true;
      detach();
      sceneRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, roll]);

  useEffect(() => () => {
    for (const timer of timers.current) window.clearTimeout(timer);
    timers.current = [];
    delete window.__NARNIA_DICE__;
  }, []);

  /** Тап по экрану: бросаем кубики. Место касания задаёт, куда они упадут. */
  const throwDice = (clientX?: number): void => {
    if (phase !== 'ready') return;
    setPhase('fall');
    window.__NARNIA_DICE__ = { values: roll.dice, phase: 'fall', verdict: roll.verdict, mode };

    if (mode === '3d') {
      const dropX = clientX === undefined ? 0 : ((clientX / window.innerWidth) * 2 - 1) * 0.6;
      sceneRef.current?.roll(roll.dice, 1 + roll.total * 31 + roll.dice[0] * 7 + roll.dice[1], dropX);
      return;
    }
    // плоский вариант: те же значения падают сверху по CSS-анимации
    setFaces(roll.dice);
    timers.current.push(window.setTimeout(showVerdict, 900));
  };

  return (
    <div
      class={`overlay overlay--dice dice-roll dice-roll--${phase}`}
      onClick={(event) => throwDice(event.clientX)}
      onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') throwDice(); }}
      role="button"
      tabIndex={0}
      aria-label={phase === 'ready' ? 'Коснись экрана, чтобы бросить кубики' : 'Кубики падают'}
    >
      {mode === '3d' && <canvas ref={canvasRef} class="dice-3d" aria-hidden="true" />}

      {mode === 'dom' && phase !== 'ready' && (
        <div class="dice dice--fall" aria-hidden="true">
          <div class="dice__die">{faces[0]}</div>
          <div class="dice__die">{faces[1]}</div>
        </div>
      )}

      {phase === 'ready' && <p class="dice-throw-hint">Коснись экрана, чтобы бросить кубики</p>}

      <div class={`dice-verdict dice-verdict--${roll.verdict}`} aria-live="polite">
        {phase === 'verdict' && (
          <>
            <p class="dice-verdict__word">{VERDICT_TEXT[roll.verdict]}</p>
            <p class="dice-verdict__note">{VERDICT_NOTE[roll.verdict]}</p>
          </>
        )}
      </div>
    </div>
  );
}
