/**
 * Значимые предметы, которые в книге записываются отметками.
 *
 * Игра ставит отметку — по правилам это «память» о находке (rules.md §4).
 * Здесь этим отметкам даны имена, чтобы лист персонажа показывал находки,
 * а не только номера: ключи нужны для финала, самоцветы — для обмена у Карги,
 * «памяти» напоминают о поступках.
 *
 * У каждого предмета есть иллюстрация: `art` — имя файла в `public/items/`
 * (нарисованы локальной ComfyUI, см. `game/HANDOFF.md`). Вещи вырезаны из фона
 * и лежат с прозрачностью, «памяти» — маленькие сцены в рамке (`scene: true`).
 */

export type TreasureKind = 'key' | 'gem' | 'boon';

export interface Treasure {
  mark: number;
  name: string;
  kind: TreasureKind;
  /** Одна строка: зачем предмет в игре. */
  effect: string;
  /** Имя иллюстрации в `public/items/<art>.webp`. */
  art: string;
  /** true — не предмет, а воспоминание: показываем сцену в круглой рамке. */
  scene?: boolean;
  note?: string;
}

