/**
 * Инвентарь героя: предметы с иллюстрациями, вкладки по видам и крупный просмотр.
 *
 * Вещи (ключи, самоцветы) нарисованы как предметы и вырезаны из фона, «памяти о поступках» —
 * маленькие сцены в круглой рамке. Данные и имена файлов — в `src/content/treasures.ts`.
 */

import { useState } from 'preact/hooks';
import type { JSX } from 'preact';

import {
  KIND_TABS, itemSrc, plainMarks, treasuresFor, type Treasure, type TreasureKind,
} from '../../content/treasures.ts';
import { Button, MarksGrid } from '../components.tsx';

const FILTERS: (TreasureKind | 'all')[] = ['all', 'key', 'gem', 'boon'];

function filterLabel(kind: TreasureKind | 'all', count: Record<string, number>): string {
  if (kind === 'all') return `Всё · ${count.all ?? 0}`;
  return `${KIND_TABS[kind]} · ${count[kind] ?? 0}`;
}

function ItemCard(props: { item: Treasure; onOpen: () => void }): JSX.Element {
  const { item } = props;
  return (
    <button
      type="button"
      class={`item item--${item.kind} ${item.scene ? 'item--scene' : ''}`}
      onClick={props.onOpen}
      title={item.effect}
    >
      <span class="item__art">
        <img src={itemSrc(item.art)} alt="" loading="lazy" />
      </span>
      <span class="item__name">{item.name}</span>
      <span class="item__kind">{KIND_TABS[item.kind]}</span>
    </button>
  );
}

export function Inventory(props: { marks: readonly number[] }): JSX.Element {
  const treasures = treasuresFor(props.marks);
  const traces = plainMarks(props.marks);
  const [filter, setFilter] = useState<TreasureKind | 'all'>('all');
  const [opened, setOpened] = useState<Treasure | null>(null);

  const count: Record<string, number> = {
    all: treasures.length,
    key: treasures.filter((t) => t.kind === 'key').length,
    gem: treasures.filter((t) => t.kind === 'gem').length,
    boon: treasures.filter((t) => t.kind === 'boon').length,
  };
  const shown = filter === 'all' ? treasures : treasures.filter((item) => item.kind === filter);

  return (
    <div class="card inventory">
      <h3 class="card__title">Инвентарь</h3>

      <div class="tabs tabs--small">
        {FILTERS.map((kind) => (
          <button
            key={kind}
            type="button"
            class={`tab ${filter === kind ? 'tab--on' : ''}`}
            onClick={() => setFilter(kind)}
          >
            {filterLabel(kind, count)}
          </button>
        ))}
      </div>

      {shown.length === 0 ? (
        <p class="hint">
          {treasures.length === 0
            ? 'Пока пусто: ключи, самоцветы и памятные находки появятся здесь.'
            : 'В этом разделе пока ничего нет.'}
        </p>
      ) : (
        <ul class="items">
          {shown.map((item) => (
            <li key={item.mark}>
              <ItemCard item={item} onOpen={() => setOpened(item)} />
            </li>
          ))}
        </ul>
      )}

      {traces.length > 0 && (
        <details class="traces">
          <summary>Следы путешествия · {traces.length}</summary>
          <p class="hint">Безымянные отметки книги: они ещё пригодятся в проверках.</p>
          <MarksGrid marks={props.marks as number[]} />
        </details>
      )}

      {opened && (
        <div class="overlay" onClick={() => setOpened(null)}>
          <div class="overlay__panel item-view" onClick={(event) => event.stopPropagation()}>
            <div class={`item-view__art ${opened.scene ? 'item-view__art--scene' : ''}`}>
              <img src={itemSrc(opened.art)} alt={opened.name} />
            </div>
            <h3 class="overlay__title">{opened.name}</h3>
            <p class="item-view__kind">{KIND_TABS[opened.kind]} · отметка {opened.mark}</p>
            <p class="item-view__effect">{opened.effect}</p>
            {opened.note && <p class="hint">{opened.note}</p>}
            <Button onClick={() => setOpened(null)}>Закрыть</Button>
          </div>
        </div>
      )}
    </div>
  );
}
