/**
 * Портреты героя (Фаза 3, экран создания персонажа).
 *
 * Готовый герой Робин и шесть своих героев — три девочки и три мальчика.
 * Картинки лежат в `public/portraits/<id>.webp` (нарисованы локальной ComfyUI
 * методом img2img от референсов владельца, см. `game/HANDOFF.md`).
 */

export interface Portrait {
  id: string;
  /** Короткая подпись в галерее. */
  label: string;
  /** Кто это: для подписи рядом с крупным портретом. */
  blurb: string;
  group: 'ready' | 'girls' | 'boys';
}

export const READY_PORTRAIT = 'robin';

export const PORTRAITS: readonly Portrait[] = [
  { id: 'robin', label: 'Робин', blurb: 'готовый герой из книги', group: 'ready' },
  { id: 'girl1', label: 'Девочка в зелёном', blurb: 'своя героиня · 9 лет', group: 'girls' },
  { id: 'girl2', label: 'Девочка с косичками', blurb: 'своя героиня · 12 лет', group: 'girls' },
  { id: 'girl3', label: 'Девочка с обручем', blurb: 'своя героиня · 10 лет', group: 'girls' },
  { id: 'boy1', label: 'Мальчик в рубашке', blurb: 'свой герой · 13 лет', group: 'boys' },
  { id: 'boy2', label: 'Мальчик в свитере', blurb: 'свой герой · 12 лет', group: 'boys' },
  { id: 'boy3', label: 'Мальчик в жилете', blurb: 'свой герой · 14 лет', group: 'boys' },
];

export const CUSTOM_PORTRAITS: readonly Portrait[] = PORTRAITS.filter((p) => p.group !== 'ready');
export const DEFAULT_CUSTOM_PORTRAIT = 'girl1';

export function portraitById(id: string | undefined): Portrait {
  return PORTRAITS.find((p) => p.id === id) ?? PORTRAITS[0]!;
}

/** Идентификатор портрета героя: у старых сохранений поля нет — считаем, что это Робин. */
export function heroPortraitId(portrait: string | undefined): string {
  return PORTRAITS.some((p) => p.id === portrait) ? portrait! : READY_PORTRAIT;
}

export function portraitSrc(id: string | undefined): string {
  return `${import.meta.env.BASE_URL}portraits/${heroPortraitId(id)}.webp`;
}
