/**
 * Карта королевства: нарисованная карта на весь экран, только перетаскивание пальцем
 * и выбор ячейки тапом (вращения и зума нет).
 *
 * Карта — это доска 6×4: столбцы 1–6 (запад→восток), ряды А–Г (север→юг). Рисунок
 * собирается заранее скриптом `tools/images/make_kingdom_map.py` из кадров ComfyUI;
 * геометрия ячеек лежит рядом с картинкой в `map/kingdom.json`.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'preact/hooks';
import type { JSX } from 'preact';

import { Button } from '../components.tsx';
import { neighbours } from '../../engine/map.ts';
import { portraitSrc } from '../../content/portraits.ts';
import type { SquareId } from '../../engine/types.ts';

export interface KingdomGeometry {
  cols: number;
  rows: number;
  padX: number;
  padTop: number;
  padBottom: number;
  squares: SquareId[];
}

const DEFAULT_GEOMETRY: KingdomGeometry = {
  cols: 6,
  rows: 4,
  padX: 0.042,
  padTop: 0.085,
  padBottom: 0.062,
  squares: ['1А', '2А', '3А', '4А', '5А', '6А', '1Б', '2Б', '3Б', '4Б', '5Б', '6Б',
    '1В', '2В', '3В', '4В', '5В', '6В', '1Г', '2Г', '3Г', '4Г', '5Г', '6Г'],
};

const ROWS = ['А', 'Б', 'В', 'Г'];

export interface KingdomCell {
  id: SquareId;
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Прямоугольники ячеек в долях от картинки: те же, что рисует скрипт сборки карты. */
export function cellRects(geometry: KingdomGeometry): KingdomCell[] {
  const cellW = (1 - 2 * geometry.padX) / geometry.cols;
  const cellH = (1 - geometry.padTop - geometry.padBottom) / geometry.rows;
  return geometry.squares.map((id) => {
    const col = Number(id[0]) - 1;
    const row = ROWS.indexOf(id.slice(1));
    return {
      id,
      x: geometry.padX + col * cellW,
      y: geometry.padTop + row * cellH,
      width: cellW,
      height: cellH,
    };
  });
}

interface DragState {
  pointerId: number;
  startX: number;
  startY: number;
  originX: number;
  originY: number;
  moved: boolean;
}

declare global {
  interface Window {
    __NARNIA_MAP__?: {
      scale: () => number;
      offset: () => { x: number; y: number };
      cells: () => (KingdomCell & { state: 'here' | 'can' | 'off'; screenX: number; screenY: number })[];
      centerOn: (id: SquareId) => void;
    };
  }
}

export function KingdomMap(props: {
  current: SquareId | null;
  visited: SquareId[];
  /** Портрет героя: на карте его место отмечено медальоном с портретом. */
  portrait: string;
  onPick: (id: SquareId) => void;
  onClose: () => void;
}): JSX.Element {
  const viewportRef = useRef<HTMLDivElement>(null);
  const boardRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<DragState | null>(null);
  const [geometry, setGeometry] = useState<KingdomGeometry>(DEFAULT_GEOMETRY);
  const [natural, setNatural] = useState({ width: 3000, height: 2000 });
  const [scale, setScale] = useState(0.2);
  const [loaded, setLoaded] = useState(false);
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const reachable = useMemo(
    () => (props.current ? neighbours(props.current) : geometry.squares),
    [props.current, geometry.squares],
  );
  const cells = useMemo(() => cellRects(geometry), [geometry]);

  const clamp = useCallback((next: { x: number; y: number }, currentScale = scale) => {
    const viewport = viewportRef.current;
    if (!viewport) return next;
    const width = natural.width * currentScale;
    const height = natural.height * currentScale;
    const minX = Math.min(0, viewport.clientWidth - width);
    const minY = Math.min(0, viewport.clientHeight - height);
    return {
      x: width <= viewport.clientWidth ? (viewport.clientWidth - width) / 2 : Math.max(minX, Math.min(0, next.x)),
      y: height <= viewport.clientHeight ? (viewport.clientHeight - height) / 2 : Math.max(minY, Math.min(0, next.y)),
    };
  }, [natural, scale]);

  /** Ставит выбранную ячейку в центр экрана (карта при этом остаётся в своих границах). */
  const centerOn = useCallback((id: SquareId, currentScale = scale, nextGeometry = geometry) => {
    const viewport = viewportRef.current;
    const cell = cellRects(nextGeometry).find((item) => item.id === id);
    if (!viewport || !cell) return;
    const pointX = (cell.x + cell.width / 2) * natural.width * currentScale;
    const pointY = (cell.y + cell.height / 2) * natural.height * currentScale;
    setOffset(clamp({ x: viewport.clientWidth / 2 - pointX, y: viewport.clientHeight / 2 - pointY }, currentScale));
  }, [clamp, geometry, natural, scale]);

  // геометрия ячеек лежит рядом с картинкой: если её нет, работает запасная
  useEffect(() => {
    let disposed = false;
    fetch(`${import.meta.env.BASE_URL}map/kingdom.json`)
      .then((response) => (response.ok ? response.json() : null))
      .then((data: KingdomGeometry | null) => {
        if (!disposed && data?.squares?.length) setGeometry(data);
      })
      .catch(() => undefined);
    return () => { disposed = true; };
  }, []);

  // при открытии карта показывает текущий квадрат целиком
  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const fit = Math.max(viewport.clientWidth / natural.width, viewport.clientHeight / natural.height);
    setScale(fit);
    if (props.current) centerOn(props.current, fit);
    else setOffset(clamp({ x: 0, y: 0 }, fit));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [natural.width, natural.height, props.current]);

  useEffect(() => {
    window.__NARNIA_MAP__ = {
      scale: () => scale,
      offset: () => offset,
      cells: () => {
        const viewport = viewportRef.current?.getBoundingClientRect();
        return cells.map((cell) => {
          const state: 'here' | 'can' | 'off' = cell.id === props.current
            ? 'here'
            : reachable.includes(cell.id) ? 'can' : 'off';
          return {
            ...cell,
            state,
            screenX: (viewport?.left ?? 0) + (cell.x + cell.width / 2) * natural.width * scale + offset.x,
            screenY: (viewport?.top ?? 0) + (cell.y + cell.height / 2) * natural.height * scale + offset.y,
          };
        });
      },
      centerOn: (id) => centerOn(id),
    };
    return () => { delete window.__NARNIA_MAP__; };
  }, [cells, centerOn, natural, offset, props.current, reachable, scale]);

  const onPointerDown = (event: PointerEvent): void => {
    if (event.button !== 0 && event.pointerType === 'mouse') return;
    const viewport = viewportRef.current;
    viewport?.setPointerCapture(event.pointerId);
    dragRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: offset.x,
      originY: offset.y,
      moved: false,
    };
  };

  const onPointerMove = (event: PointerEvent): void => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const dx = event.clientX - drag.startX;
    const dy = event.clientY - drag.startY;
    if (!drag.moved && Math.hypot(dx, dy) > 8) drag.moved = true;
    if (drag.moved) setOffset(clamp({ x: drag.originX + dx, y: drag.originY + dy }));
  };

  const onPointerUp = (event: PointerEvent): void => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    viewportRef.current?.releasePointerCapture(event.pointerId);
    // Палец не сдвинулся — это выбор ячейки. Клик по кнопке сюда не доходит:
    // указатель захвачен окном карты, поэтому ищем клетку под точкой отпускания.
    if (!drag.moved) {
      const element = document.elementFromPoint(event.clientX, event.clientY);
      const cell = element?.closest<HTMLElement>('.map2d__cell--can');
      const id = cell?.dataset.square as SquareId | undefined;
      if (id) props.onPick(id);
    }
  };

  return (
    <div class="map2d">
      <div class="map2d__bar">
        <div>
          <h3 class="map2d__title">Куда идём{props.current ? ` из ${props.current}` : ''}?</h3>
          <p class="map2d__hint">Тащи карту пальцем · коснись соседней клетки, чтобы перейти</p>
        </div>
        <div class="map2d__buttons">
          <Button kind="ghost" onClick={() => props.current && centerOn(props.current)}>К герою</Button>
          <Button onClick={props.onClose}>Закрыть</Button>
        </div>
      </div>

      <div
        class="map2d__viewport"
        ref={viewportRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
      >
        <div
          class="map2d__board"
          ref={boardRef}
          style={{
            width: `${natural.width}px`,
            height: `${natural.height}px`,
            transform: `translate3d(${offset.x}px, ${offset.y}px, 0) scale(${scale})`,
          }}
        >
          <img
            class="map2d__image"
            src={`${import.meta.env.BASE_URL}map/kingdom.webp`}
            alt="Карта королевства"
            draggable={false}
            onLoad={(event) => {
              const image = event.currentTarget as HTMLImageElement;
              if (image.naturalWidth) setNatural({ width: image.naturalWidth, height: image.naturalHeight });
              setLoaded(true);
            }}
          />
          <div class="map2d__cells">
            {cells.map((cell) => {
              const here = cell.id === props.current;
              const can = !here && reachable.includes(cell.id);
              const visited = props.visited.includes(cell.id);
              return (
                <button
                  type="button"
                  key={cell.id}
                  class={`map2d__cell ${here ? 'map2d__cell--here' : ''} ${can ? 'map2d__cell--can' : ''} ${visited ? 'map2d__cell--seen' : ''}`}
                  style={{
                    left: `${cell.x * 100}%`,
                    top: `${cell.y * 100}%`,
                    width: `${cell.width * 100}%`,
                    height: `${cell.height * 100}%`,
                  }}
                  data-square={cell.id}
                  disabled={!can}
                  onClick={() => can && props.onPick(cell.id)}
                  aria-label={here ? `Ты здесь: ${cell.id}` : `Идти в квадрат ${cell.id}`}
                >
                  {here && (
                    <span class="map2d__hero" aria-hidden="true">
                      <img src={portraitSrc(props.portrait)} alt="" />
                    </span>
                  )}
                  {can && <span class="map2d__marker" aria-hidden="true" />}
                </button>
              );
            })}
          </div>
        </div>

        {!loaded && <p class="map2d__loading">Разворачиваем карту…</p>}

        <p class="map2d__scale" aria-hidden="true">
          {props.current ? `Ты в квадрате ${props.current}` : 'Квадрат не выбран'}
        </p>
      </div>
    </div>
  );
}
